#!/usr/bin/env bash
# Agent Teams teammate installer (self-contained). Generated by build-installer.sh.
# Usage: bash <this-file> [--label NAME] [--dir DIR] [--codex-home DIR] [--private-codex-home] [--device-auth] [--no-service] [--no-desktop] [--desktop-app PATH]
# Uses the selected stock or bundled fork runtime. Worker and client share its App Server.
# Uses the user's existing Codex home/login by default; runtime state remains private to the install.
set -euo pipefail

RELAY_URL="__RELAY_URL__"
WORKER_TOKEN="__WORKER_TOKEN__"
TEAM_ID="__TEAM_ID__"
RUNTIME_KIND="__RUNTIME_KIND__"
case "$RUNTIME_KIND" in __*) RUNTIME_KIND=fork ;; esac
case "$RUNTIME_KIND" in fork|stock) ;; *) echo "Invalid installer runtime" >&2; exit 2 ;; esac
NODE_MAJOR="24"
NODE_MIN="24.15.0"
APP_SERVER_START_TIMEOUT_SECONDS="${AGENT_TEAMS_APP_SERVER_START_TIMEOUT_SECONDS:-1800}"
case "$APP_SERVER_START_TIMEOUT_SECONDS" in ''|*[!0-9]*) echo 'App Server startup timeout must be an integer from 1 to 7200 seconds' >&2; exit 2 ;; esac
[ "$APP_SERVER_START_TIMEOUT_SECONDS" -ge 1 ] && [ "$APP_SERVER_START_TIMEOUT_SECONDS" -le 7200 ] || { echo 'App Server startup timeout must be from 1 to 7200 seconds' >&2; exit 2; }
APP_SERVER_START_TIMEOUT_SECONDS=$((10#$APP_SERVER_START_TIMEOUT_SECONDS))

LABEL="$(hostname -s 2>/dev/null || hostname)"
DIR="${HOME}/.local/share/agent-teams/mate-${TEAM_ID:0:8}"
[ "$RUNTIME_KIND" != stock ] || DIR="${DIR}-stock"
SERVICE=1
OPEN_DESKTOP=1
DESKTOP_APP=""
CODEX_HOME_DIR=""
PRIVATE_CODEX_HOME=0
DEVICE_AUTH=0
SELECTED_CODEX=""
SERVER_OWNERSHIP=managed
EXTERNAL_SOCKET=""
while [ $# -gt 0 ]; do
  case "$1" in
    --label) LABEL="$2"; shift 2 ;;
    --dir) DIR="$2"; shift 2 ;;
    --codex-binary) SELECTED_CODEX="$2"; shift 2 ;;
    --server-ownership) SERVER_OWNERSHIP="$2"; shift 2 ;;
    --app-server-socket) EXTERNAL_SOCKET="$2"; shift 2 ;;
    --codex-home) CODEX_HOME_DIR="$2"; shift 2 ;;
    --private-codex-home) PRIVATE_CODEX_HOME=1; shift ;;
    --existing-codex-home) PRIVATE_CODEX_HOME=0; shift ;;
    --device-auth) DEVICE_AUTH=1; shift ;;
    --no-service) SERVICE=0; shift ;;
    --no-desktop) OPEN_DESKTOP=0; shift ;;
    --desktop-app) DESKTOP_APP="$2"; OPEN_DESKTOP=1; shift 2 ;;
    -h|--help) sed -n '2,5p' "$0"; exit 0 ;;
    *) echo "unknown option: $1" >&2; exit 2 ;;
  esac
done

say() { printf '\033[1;34m==>\033[0m %s\n' "$*"; }
die() { printf '\033[1;31merror:\033[0m %s\n' "$*" >&2; exit 1; }

case "$SERVER_OWNERSHIP" in managed|external) ;; *) die "--server-ownership must be managed or external" ;; esac
if [ "$SERVER_OWNERSHIP" = external ]; then
  [ "$RUNTIME_KIND" = stock ] || die "External App Server mode is supported by the stock installer"
  [ -n "$EXTERNAL_SOCKET" ] && [ -n "$CODEX_HOME_DIR" ] || die "External mode requires --app-server-socket and --codex-home matching the server"
  [ -S "$EXTERNAL_SOCKET" ] && [ ! -L "$EXTERNAL_SOCKET" ] || die "External App Server socket is not available"
else
  [ -z "$EXTERNAL_SOCKET" ] || die "--app-server-socket requires --server-ownership external"
fi

OS="$(uname -s)"; ARCH="$(uname -m)"
case "$OS" in Darwin) NODE_OS=darwin ;; Linux) NODE_OS=linux ;; *) die "unsupported OS: $OS" ;; esac
case "$ARCH" in arm64|aarch64) NODE_ARCH=arm64 ;; x86_64) NODE_ARCH=x64 ;; *) die "unsupported CPU: $ARCH" ;; esac

version_ge() { [ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -1)" = "$2" ]; }

LEGACY_INSTALL=0
if [ -f "$DIR/installation.json" ]; then
  EXISTING_KIND=$(sed -n 's/.*"runtimeKind":"\([a-z]*\)".*/\1/p' "$DIR/installation.json")
  [ "$EXISTING_KIND" = "$RUNTIME_KIND" ] || die "Installation runtime differs; choose a new --dir to keep both installations"
elif [ "$RUNTIME_KIND" = stock ] && [ -s "$DIR/config.env" ]; then
  die "Existing legacy installation is a fork; choose a new --dir"
elif [ -s "$DIR/config.env" ]; then LEGACY_INSTALL=1
fi
say "Installing Agent Teams teammate '${LABEL}' into ${DIR}"
umask 077
mkdir -p "$DIR/worker" "$DIR/data" "$DIR/workspace" "$DIR/logs" "$DIR/bin" "$DIR/codex-state"
DIR="$(cd "$DIR" && pwd)"
chmod 700 "$DIR" "$DIR/data" "$DIR/workspace"
# Stop the previous installation before replacing any of its executable files.
# macOS TMPDIR paths can exceed the Unix socket limit before the socket name is appended.
SOCK_DIR="/tmp/agent-teams-$(id -u)"; mkdir -p "$SOCK_DIR"; chmod 700 "$SOCK_DIR"
DIR_SUM=$(printf '%s' "$DIR" | cksum | cut -d' ' -f1)
CONTROL_SOCK="$SOCK_DIR/mate-${TEAM_ID:0:8}-${DIR_SUM}.sock"
APP_SERVER_SOCK="$SOCK_DIR/codex-${TEAM_ID:0:8}-${DIR_SUM}.sock"
if [ -f "$DIR/bin/stop.sh" ] && [ ! -L "$DIR/bin/stop.sh" ]; then
  say "Stopping the existing installation before updating"
  bash "$DIR/bin/stop.sh" || die "Could not stop this installation; inspect its logs before updating"
fi
# An unsuccessful stop must never authorize overwriting a live runtime or adopting its socket.
if [ -f "$DIR/data/supervisor.pid" ]; then
  SUPERVISOR_PID=$(cat "$DIR/data/supervisor.pid")
  case "$SUPERVISOR_PID" in ''|*[!0-9]*) die "Invalid supervisor PID; inspect $DIR/data/supervisor.pid" ;; esac
  ! kill -0 "$SUPERVISOR_PID" 2>/dev/null || die "Stop this installation before updating its runtime: $APP_SERVER_SOCK"
fi
if [ "$SERVER_OWNERSHIP" = external ]; then APP_SERVER_SOCK="$EXTERNAL_SOCKET";
else [ ! -e "$APP_SERVER_SOCK" ] && [ ! -L "$APP_SERVER_SOCK" ] || die "Stop this installation before updating its runtime: $APP_SERVER_SOCK"; fi

# --- worker bundle (embedded) -------------------------------------------------
say "Unpacking worker bundle"
PAYLOAD_LINE=$(awk '/^__PAYLOAD_BELOW__$/ { print NR + 1; exit 0; }' "$0")
tail -n +"$PAYLOAD_LINE" "$0" | base64 -d | tar -xzf - -C "$DIR/worker"
[ -s "$DIR/worker/cli.js" ] && [ -s "$DIR/worker/localWorkerCli.js" ] || die "Worker bundle is missing its local relay launcher"

# --- node ---------------------------------------------------------------------
NODE=""
if command -v node >/dev/null 2>&1; then
  v="$(node --version | sed 's/^v//')"
  if version_ge "$v" "$NODE_MIN" && [ "${v%%.*}" = "$NODE_MAJOR" ]; then NODE="$(command -v node)"; fi
fi
if [ -z "$NODE" ] && [ -x "$DIR/node/bin/node" ]; then NODE="$DIR/node/bin/node"; fi
if [ -z "$NODE" ]; then
  say "Node ${NODE_MAJOR} not found; downloading a private copy"
  tarball="$(curl -fsSL "https://nodejs.org/dist/latest-v${NODE_MAJOR}.x/SHASUMS256.txt" | awk -v f="${NODE_OS}-${NODE_ARCH}.tar.gz" '$2 ~ f {print $2; exit}')"
  [ -n "$tarball" ] || die "could not resolve a Node ${NODE_MAJOR} download for ${NODE_OS}-${NODE_ARCH}"
  tmp="$(mktemp -d)"; curl -fsSL "https://nodejs.org/dist/latest-v${NODE_MAJOR}.x/${tarball}" -o "$tmp/node.tgz"
  rm -rf "$DIR/node"; mkdir -p "$DIR/node"; tar -xzf "$tmp/node.tgz" -C "$DIR/node" --strip-components=1; rm -rf "$tmp"
  NODE="$DIR/node/bin/node"
fi
say "Node: $("$NODE" --version) at $NODE"

# --- selected Codex runtime ---------------------------------------------------
APP_TO_OPEN="$DESKTOP_APP"
if [ "$OS" = Darwin ] && [ "$OPEN_DESKTOP" = 1 ] && [ -z "$APP_TO_OPEN" ]; then
  for CANDIDATE in /Applications/Codex.app "$HOME/Applications/Codex.app" /Applications/ChatGPT.app "$HOME/Applications/ChatGPT.app"; do
    if [ -d "$CANDIDATE/Contents/MacOS" ]; then APP_TO_OPEN="$CANDIDATE"; break; fi
  done
fi
if [ "$RUNTIME_KIND" = stock ]; then
  # The desktop's official server is version-matched to its startup policy protocol.
  if [ -z "$SELECTED_CODEX" ] && [ "$OPEN_DESKTOP" = 1 ] && [ -n "$APP_TO_OPEN" ]; then
    for CANDIDATE in "$APP_TO_OPEN/Contents/Resources/codex-cli/bin/codex" "$APP_TO_OPEN/Contents/Resources/codex"; do
      if [ -x "$CANDIDATE" ]; then SELECTED_CODEX="$CANDIDATE"; break; fi
    done
  fi
  [ -n "$SELECTED_CODEX" ] || SELECTED_CODEX="$(command -v codex || true)"
  [ -n "$SELECTED_CODEX" ] && [ -x "$SELECTED_CODEX" ] || die "Stock Codex was not found. Install official Codex or pass --codex-binary PATH"
  CODEX=$("$NODE" -e 'process.stdout.write(require("node:path").resolve(process.argv[1]))' "$SELECTED_CODEX")
  "$CODEX" app-server --help 2>&1 | grep -q -- --listen || die "Selected Codex does not support App Server --listen"
  "$CODEX" agents --help 2>&1 | grep -q -- --remote || die "Selected Codex does not support agents --remote"
else
  [ -z "$SELECTED_CODEX" ] || die "--codex-binary is available only for stock installers"
RUNTIME_DIR="$DIR/worker/codex-runtime/${NODE_OS}-${NODE_ARCH}"
CODEX="$RUNTIME_DIR/bin/codex"
[ -x "$CODEX" ] || die "Installer has no forked Codex runtime for ${NODE_OS}-${NODE_ARCH}. Ask for a matching installer."
# Verify the entire staged package before executing any fork code.
"$NODE" --input-type=module - "$RUNTIME_DIR" "${NODE_OS}-${NODE_ARCH}" <<'VERIFY_RUNTIME'
import { createHash } from 'node:crypto';
import { lstat, readFile, readdir } from 'node:fs/promises';
import { join } from 'node:path';
const [root, platform] = process.argv.slice(2);
const manifest = JSON.parse(await readFile(join(root, 'runtime-manifest.json'), 'utf8'));
if (manifest.schemaVersion !== 1 || manifest.platform !== platform ||
    typeof manifest.revision !== 'string' || !manifest.revision.trim() ||
    !manifest.files || typeof manifest.files !== 'object' || Array.isArray(manifest.files) ||
    !Object.hasOwn(manifest.files, 'bin/codex')) throw new Error('Invalid fork runtime manifest');
const seen = new Set();
async function verify(directory, prefix = '') {
  for (const name of await readdir(directory)) {
    const relative = prefix + name;
    const path = join(directory, name);
    const stat = await lstat(path);
    if (stat.isSymbolicLink()) throw new Error(`Runtime contains a symlink: ${relative}`);
    if (stat.isDirectory()) await verify(path, relative + '/');
    else if (stat.isFile() && relative === 'runtime-manifest.json') continue;
    else if (stat.isFile()) {
      const digest = createHash('sha256').update(await readFile(path)).digest('hex');
      if (manifest.files[relative] !== digest) throw new Error(`Runtime checksum mismatch: ${relative}`);
      seen.add(relative);
    } else throw new Error(`Invalid runtime entry: ${relative}`);
  }
}
await verify(root);
if (seen.size !== Object.keys(manifest.files).length) throw new Error('Runtime package is incomplete');
console.log(`Codex fork: ${manifest.revision} (${manifest.platform})`);
VERIFY_RUNTIME
fi
say "Codex: $("$CODEX" --version) at $CODEX"
if [ -z "$CODEX_HOME_DIR" ]; then
  if [ "$PRIVATE_CODEX_HOME" = 1 ]; then CODEX_HOME_DIR="$DIR/codex-home";
  else CODEX_HOME_DIR="${CODEX_HOME:-$HOME/.codex}"; fi
fi
APP_SERVER_MODE=shared-daemon
mkdir -p "$CODEX_HOME_DIR"
# Validate without changing an existing user's home permissions or following a symlink.
CODEX_HOME_DIR=$("$NODE" -e '
const fs = require("node:fs"); const path = require("node:path");
const home = path.resolve(process.argv[1]); const stat = fs.lstatSync(home);
if (home === path.parse(home).root || !stat.isDirectory() || stat.isSymbolicLink() || (stat.mode & 0o077)) {
  throw new Error("Codex home must be a private directory (0700), not a root or symlink. Choose --private-codex-home for a separate sign-in.");
}
process.stdout.write(home);
' "$CODEX_HOME_DIR")
if ! CODEX_HOME="$CODEX_HOME_DIR" "$CODEX" login status >/dev/null 2>&1; then
  if [ "$RUNTIME_KIND" = stock ] && [ "$DEVICE_AUTH" != 1 ]; then
    die "No existing Codex login is available at $CODEX_HOME_DIR. Open Codex and sign in there, then rerun this installer. No new sign-in was started."
  fi
  # Use this home's credential store directly; never copy auth.json into another home.
  [ -t 0 ] || die "Codex home $CODEX_HOME_DIR is not signed in. Run this installer in a terminal, or first run: CODEX_HOME=$CODEX_HOME_DIR codex login --device-auth"
  if [ "$DEVICE_AUTH" = 1 ] || [ -n "${SSH_CONNECTION:-}" ]; then LOGIN_ARGS=(login --device-auth); else LOGIN_ARGS=(login); fi
  say "Sign in to Codex at $CODEX_HOME_DIR"
  CODEX_HOME="$CODEX_HOME_DIR" "$CODEX" "${LOGIN_ARGS[@]}" || die "Codex sign-in did not complete"
  CODEX_HOME="$CODEX_HOME_DIR" "$CODEX" login status >/dev/null 2>&1 || die "Codex home $CODEX_HOME_DIR is still not signed in"
fi
say "Using Codex login from $CODEX_HOME_DIR (runtime: $RUNTIME_KIND)"
[ "$SERVER_OWNERSHIP" != external ] || say "External App Server home is operator-owned; its operator manages runtime storage isolation"

# --- identity + config --------------------------------------------------------
uuid() { "$NODE" -e "console.log(require('crypto').randomUUID())"; }
# Unix socket paths are limited to ~100 characters, so keep the control socket in a short, private dir.
# Unique per install directory, so two members of one team on the same machine never share a socket.
# Kept short because Unix socket paths are limited to about 100 characters.
INSTALLATION_META=$("$NODE" -e '
const fs = require("node:fs"); const {randomUUID} = require("node:crypto");
const file = process.argv[1]; let descriptor;
try { descriptor = JSON.parse(fs.readFileSync(file, "utf8")); }
catch (error) { if (error.code !== "ENOENT") throw error; }
if (descriptor && descriptor.runtimeKind !== process.argv[2]) throw new Error("Installation runtime mismatch");
if (!descriptor) {
  const id = randomUUID();
  descriptor = {schemaVersion:1,installationId:id,runtimeKind:process.argv[2],controlMcpName:process.argv[3] === "1" ? "agent-teams-control" : "agent_teams_control_" + id.replaceAll("-", "")};
  fs.writeFileSync(file,JSON.stringify(descriptor)+"\n",{mode:0o600});
}
if (!/^[a-f0-9-]{36}$/.test(descriptor.installationId)) throw new Error("Invalid installation identity");
if (!/^(agent-teams-control|agent_teams_control_[a-f0-9]{32})$/.test(descriptor.controlMcpName)) throw new Error("Invalid control MCP identity");
process.stdout.write(descriptor.installationId + " " + descriptor.controlMcpName);
' "$DIR/installation.json" "$RUNTIME_KIND" "$LEGACY_INSTALL")
read -r INSTALLATION_ID CONTROL_MCP_NAME <<< "$INSTALLATION_META"
ENV_FILE="$DIR/config.env"
if [ ! -s "$ENV_FILE" ]; then
  {
    printf 'AGENT_TEAMS_RELAY_WORKER_TOKEN=%q\n' "$WORKER_TOKEN"
    printf 'AGENT_TEAMS_AUTO_JOIN_TEAM_ID=%q\n' "$TEAM_ID"
    printf 'AGENT_TEAMS_RELAY_URL=%q\n' "$RELAY_URL"
    printf 'AGENT_TEAMS_LABEL=%q\n' "$LABEL"
    printf 'AGENT_TEAMS_ORGANIZATION_ID=%q\n' "$(uuid)"
    printf 'AGENT_TEAMS_PERSON_ID=%q\n' "$(uuid)"
    printf 'AGENT_TEAMS_NODE_ID=%q\n' "$(uuid)"
    printf 'AGENT_TEAMS_WORKER_INSTANCE_ID=%q\n' "$(uuid)"
  } >"$ENV_FILE"
  chmod 600 "$ENV_FILE"
fi

{
  printf '#!/usr/bin/env bash\nset -euo pipefail\numask 077\n'
  printf 'NODE=%q\nCODEX=%q\nCODEX_HOME=%q\nAPP_SERVER_SOCK=%q\nCONTROL_SOCK=%q\nDIR=%q\nENV_FILE=%q\n' \
    "$NODE" "$CODEX" "$CODEX_HOME_DIR" "$APP_SERVER_SOCK" "$CONTROL_SOCK" "$DIR" "$ENV_FILE"
  printf 'RUNTIME_KIND=%q\nSERVER_OWNERSHIP=%q\nINSTALLATION_ID=%q\nCONTROL_MCP_NAME=%q\n' "$RUNTIME_KIND" "$SERVER_OWNERSHIP" "$INSTALLATION_ID" "$CONTROL_MCP_NAME"
  printf 'APP_SERVER_START_TIMEOUT_SECONDS=%q\n' "$APP_SERVER_START_TIMEOUT_SECONDS"
  cat <<'START_WORKER'
export CODEX_HOME
# macOS launchd defaults to 256 descriptors; persistent chats each keep MCP pipes open.
NOFILE_LIMIT=$(ulimit -n)
case "$NOFILE_LIMIT" in
  unlimited) ;;
  *) [ "$NOFILE_LIMIT" -ge 4096 ] || ulimit -n 4096 || true ;;
esac
set -a; source "$ENV_FILE"; set +a
# Do not adopt another server or silently change the selected runtime.
if [ "$SERVER_OWNERSHIP" = managed ]; then
[ ! -e "$APP_SERVER_SOCK" ] && [ ! -L "$APP_SERVER_SOCK" ] || {
  echo "App Server socket already exists: $APP_SERVER_SOCK; stop the owning installation first" >&2; exit 1;
}
else [ -S "$APP_SERVER_SOCK" ] && [ ! -L "$APP_SERVER_SOCK" ] || { echo "External App Server is unavailable" >&2; exit 1; }; fi
server_pid=""; worker_pid=""
"$NODE" - "$DIR/data/supervisor.pid" "$$" <<'ACQUIRE_SUPERVISOR_LOCK'
const { linkSync, mkdirSync, lstatSync, readdirSync, readFileSync, writeFileSync, unlinkSync } = require('node:fs');
const { randomUUID } = require('node:crypto');
const { join } = require('node:path');
// Publish complete files exclusively; interrupted writes leave only private temporaries.
const publishLockFile = (path, content) => {
  const temporary = path + '.' + randomUUID() + '.tmp';
  try {
    writeFileSync(temporary, content, { flag: 'wx', mode: 0o600 });
    try { linkSync(temporary, path); return true; }
    catch (error) { if (error.code === 'EEXIST') return false; throw error; }
  } finally {
    try { unlinkSync(temporary); } catch { /* Private temporaries never control ownership. */ }
  }
};
// Immutable generations recover dead reclaimers without unlinking another guard.
// Do not delete this journal while the installation may be running.
const withLockReclamation = (file, operation) => {
  const directory = file + '.reclaims';
  mkdirSync(directory, { recursive: true, mode: 0o700 });
  const stat = lstatSync(directory);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error('Invalid lock journal');
  while (true) {
    const latest = readdirSync(directory).filter(name => /^\d{16}\.json$/.test(name)).sort().at(-1);
    let generation = 1;
    if (latest) {
      const previous = join(directory, latest);
      const owner = JSON.parse(readFileSync(previous, 'utf8'));
      if (!owner || !Number.isSafeInteger(owner.pid) || owner.pid < 1 || typeof owner.token !== 'string' || !owner.token)
        throw new Error('Invalid lock journal identity');
      let completed = false;
      try {
        completed = readFileSync(previous + '.done', 'utf8') === owner.token;
        if (!completed) throw new Error('Invalid lock journal completion');
      } catch (error) { if (error.code !== 'ENOENT') throw error; }
      if (!completed) {
        try { process.kill(owner.pid, 0); return false; }
        catch (error) {
          if (error.code === 'EPERM') return false;
          if (error.code !== 'ESRCH') throw error;
        }
      }
      generation = Number(latest.slice(0, 16)) + 1;
      if (!Number.isSafeInteger(generation)) throw new Error('Lock journal exhausted');
    }
    const record = join(directory, String(generation).padStart(16, '0') + '.json');
    const token = randomUUID();
    if (!publishLockFile(record, JSON.stringify({ pid: process.pid, token }))) continue;
    try { operation(); }
    finally { publishLockFile(record + '.done', token); }
    return true;
  }
};
const [file, pidValue] = process.argv.slice(2);
const pid = Number(pidValue);
if (!Number.isSafeInteger(pid) || pid <= 1) throw new Error('Invalid supervisor process ID');
for (let attempt = 0; attempt < 3; attempt++) {
  if (publishLockFile(file, String(pid) + '\n')) process.exit(0);
  if (!withLockReclamation(file, () => {
    let stat, content;
    try { stat = lstatSync(file); content = readFileSync(file, 'utf8'); }
    catch (error) { if (error.code === 'ENOENT') return; throw error; }
    if (!stat.isFile() || stat.isSymbolicLink() || !/^[1-9][0-9]*\s*$/.test(content))
      throw new Error('Invalid supervisor lock; inspect it before restarting');
    const previousPid = Number(content.trim());
    if (!Number.isSafeInteger(previousPid) || previousPid <= 1) throw new Error('Invalid previous supervisor process ID');
    try {
      process.kill(previousPid, 0);
      throw new Error('This installation is already running or its PID belongs to another live process: ' + previousPid);
    } catch (error) { if (error.code !== 'ESRCH') throw error; }
    try {
      const current = lstatSync(file);
      if (current.dev === stat.dev && current.ino === stat.ino && readFileSync(file, 'utf8') === content) unlinkSync(file);
    } catch (error) { if (error.code !== 'ENOENT') throw error; }
  })) throw new Error('Supervisor lock recovery is already in progress; retry after checking its owner');
}
throw new Error('Supervisor lock was claimed concurrently; retry after checking its owner');
ACQUIRE_SUPERVISOR_LOCK
cleanup() {
  trap - EXIT INT TERM
  [ -z "$worker_pid" ] || kill "$worker_pid" 2>/dev/null || true
  [ -z "$server_pid" ] || kill "$server_pid" 2>/dev/null || true
  [ -z "$worker_pid" ] || wait "$worker_pid" 2>/dev/null || true
  [ -z "$server_pid" ] || wait "$server_pid" 2>/dev/null || true
  if [ "$SERVER_OWNERSHIP" = managed ]; then [ ! -S "$APP_SERVER_SOCK" ] || rm -f "$APP_SERVER_SOCK"; fi
  [ "$(cat "$DIR/data/supervisor.pid" 2>/dev/null)" != "$$" ] || rm -f "$DIR/data/supervisor.pid"
}
trap cleanup EXIT
trap 'exit 0' INT TERM
# A previous launch's persisted snapshot must never satisfy this launch's readiness check.
rm -f "$DIR/data/worker-status.json"
SQLITE_CONFIG=$("$NODE" -e 'process.stdout.write("sqlite_home=" + JSON.stringify(process.argv[1]))' "$DIR/codex-state")
LOG_CONFIG=$("$NODE" -e 'process.stdout.write("log_dir=" + JSON.stringify(process.argv[1]))' "$DIR/logs")
if [ "$SERVER_OWNERSHIP" = managed ]; then
"$CODEX" -c "$SQLITE_CONFIG" -c "$LOG_CONFIG" app-server --listen "unix://$APP_SERVER_SOCK" >>"$DIR/logs/app-server.log" 2>&1 &
server_pid=$!
# Initial rollout backfill can take minutes; killing it early leaves a 15-minute lease.
startup_deadline=$((SECONDS + APP_SERVER_START_TIMEOUT_SECONDS))
next_startup_notice=$((SECONDS + 10))
while [ ! -S "$APP_SERVER_SOCK" ]; do
  kill -0 "$server_pid" 2>/dev/null || { echo "App Server exited during startup; inspect $DIR/logs/app-server.log" >&2; exit 1; }
  [ "$SECONDS" -lt "$startup_deadline" ] || { echo "App Server socket did not become ready after ${APP_SERVER_START_TIMEOUT_SECONDS}s; inspect $DIR/logs/app-server.log" >&2; exit 1; }
  if [ "$SECONDS" -ge "$next_startup_notice" ]; then
    echo "Waiting for the local App Server socket; database backfill may still be running. Log: $DIR/logs/app-server.log"
    next_startup_notice=$((SECONDS + 30))
  fi
  sleep 0.2
done
fi
EXTRA_WORKER_ARGS=(--runtime-kind "$RUNTIME_KIND" --server-ownership "$SERVER_OWNERSHIP" --installation-id "$INSTALLATION_ID" --control-mcp-name "$CONTROL_MCP_NAME")
[ "$(uname -s)" != Darwin ] || EXTRA_WORKER_ARGS+=(--desktop-launcher "$DIR/bin/desktop.sh")
"$NODE" "$DIR/worker/localWorkerCli.js" start --app-server-mode shared-daemon --app-server-connect-only \
  --app-server-socket "$APP_SERVER_SOCK" \
  --relay "$AGENT_TEAMS_RELAY_URL" --data-dir "$DIR/data" --control-socket "$CONTROL_SOCK" \
  --codex-home "$CODEX_HOME" --runtime-cwd "$DIR/workspace" --codex-binary "$CODEX" \
  "${EXTRA_WORKER_ARGS[@]}" \
  --label "$AGENT_TEAMS_LABEL" --organization-id "$AGENT_TEAMS_ORGANIZATION_ID" \
  --person-id "$AGENT_TEAMS_PERSON_ID" --node-id "$AGENT_TEAMS_NODE_ID" \
  --worker-instance-id "$AGENT_TEAMS_WORKER_INSTANCE_ID" &
worker_pid=$!
while kill -0 "$worker_pid" 2>/dev/null; do
  [ "$SERVER_OWNERSHIP" = external ] || kill -0 "$server_pid" 2>/dev/null || break
  sleep 1
done
# Either process exiting restarts this installation through launchd/systemd.
exit 1
START_WORKER
} >"$DIR/bin/start.sh"
cat >"$DIR/bin/status.sh" <<EOF
#!/usr/bin/env bash
"$NODE" "$DIR/worker/cli.js" status --runtime-kind "$RUNTIME_KIND" --server-ownership "$SERVER_OWNERSHIP" --installation-id "$INSTALLATION_ID" --control-mcp-name "$CONTROL_MCP_NAME" --data-dir "$DIR/data" --control-socket "$CONTROL_SOCK" --codex-home "$CODEX_HOME_DIR" --app-server-mode ${APP_SERVER_MODE} --app-server-connect-only --app-server-socket "$APP_SERVER_SOCK"
echo; echo "--- live worker status ---"; cat "$DIR/data/worker-status.json" 2>/dev/null || echo "(not started yet)"
EOF
{
  printf '#!/usr/bin/env bash\nset -euo pipefail\n'
  printf 'export CODEX_HOME=%q\nCODEX=%q\nAPP_SERVER_SOCK=%q\nNODE=%q\nSTATE_DIR=%q\nRUNTIME_KIND=%q\n' "$CODEX_HOME_DIR" "$CODEX" "$APP_SERVER_SOCK" "$NODE" "$DIR/codex-state" "$RUNTIME_KIND"
  cat <<'ATTACH_CLIENT'
[ -S "$APP_SERVER_SOCK" ] || { echo 'App Server is not running; start this installation first.' >&2; exit 1; }
[ "$RUNTIME_KIND" != stock ] || exec "$CODEX" agents --remote "unix://$APP_SERVER_SOCK" "$@"
SQLITE_CONFIG=$("$NODE" -e 'process.stdout.write("sqlite_home=" + JSON.stringify(process.argv[1]))' "$STATE_DIR")
exec "$CODEX" -c "$SQLITE_CONFIG" agents --remote "unix://$APP_SERVER_SOCK" "$@"
ATTACH_CLIENT
} >"$DIR/bin/attach.sh"

# The desktop app speaks WebSocket. Forward its connection to the same private daemon socket.
cat >"$DIR/bin/desktop-bridge.mjs" <<'DESKTOP_BRIDGE'
import { randomBytes } from 'node:crypto';
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { connect } from 'node:net';

const [socketPath, _codex, home, userData, executable, ...args] = process.argv.slice(2);
if (!executable) throw new Error('Desktop executable is required');
const capabilityPath = '/' + randomBytes(32).toString('hex');
const sockets = new Set();
const server = createServer((_request, response) => { response.writeHead(404); response.end(); });
server.on('connection', socket => {
  sockets.add(socket);
  socket.on('error', () => {});
  socket.on('close', () => sockets.delete(socket));
});
server.on('upgrade', (request, client, head) => {
  if (request.url !== capabilityPath) {
    client.end('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');
    return;
  }
  const upstream = connect(socketPath);
  sockets.add(upstream);
  upstream.on('close', () => { sockets.delete(upstream); client.end(); });
  upstream.on('error', () => client.destroy());
  client.on('close', () => upstream.destroy());
  upstream.on('connect', () => {
    const headers = request.rawHeaders;
    let handshake = 'GET / HTTP/1.1\r\n';
    for (let i = 0; i < headers.length; i += 2) handshake += headers[i] + ': ' + headers[i + 1] + '\r\n';
    upstream.write(handshake + '\r\n');
    if (head.length) upstream.write(head);
    client.pipe(upstream).pipe(client);
  });
});
server.on('error', error => { console.error('Desktop bridge failed:', error.message); process.exitCode = 1; });
await new Promise((resolve, reject) => {
  server.once('error', reject);
  server.listen(0, '127.0.0.1', resolve);
});
const env = {
  ...process.env,
  CODEX_HOME: home,
  CODEX_APP_SERVER_WS_URL: 'ws://127.0.0.1:' + server.address().port + capabilityPath,
  CODEX_ELECTRON_USER_DATA_PATH: userData,
};
delete env.CODEX_APP_SERVER_FORCE_CLI;
// Keep the app's version-matched startup/policy reader; only its runtime transport is redirected.
delete env.CODEX_CLI_PATH;
const child = spawn(executable, args, { env, stdio: 'inherit' });
const cleanup = () => { for (const socket of sockets) socket.destroy(); server.close(); };
child.on('error', error => { console.error('Could not open Codex desktop:', error.message); process.exitCode = 1; cleanup(); });
child.on('exit', code => { process.exitCode = code ?? 1; cleanup(); });
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => { child.kill(signal); cleanup(); });
console.error('Codex desktop is connecting to the existing customized App Server.');
DESKTOP_BRIDGE
{
  printf '#!/usr/bin/env bash\nset -euo pipefail\numask 077\n'
  printf 'NODE=%q\nCODEX=%q\nCODEX_HOME_DIR=%q\nAPP_SERVER_SOCK=%q\nDIR=%q\n' "$NODE" "$CODEX" "$CODEX_HOME_DIR" "$APP_SERVER_SOCK" "$DIR"
  printf 'CONTROL_SOCK=%q\nRUNTIME_KIND=%q\n' "$CONTROL_SOCK" "$RUNTIME_KIND"
  cat <<'ATTACH_DESKTOP'
[ "$(uname -s)" = Darwin ] || { echo 'Desktop launcher currently supports macOS.' >&2; exit 1; }
[ -S "$APP_SERVER_SOCK" ] || { echo 'App Server is not running; start this installation first.' >&2; exit 1; }
# Reuse this installation's window; another process using the same Electron profile is unsafe.
if [ -s "$DIR/desktop-data/team-desktop.pid" ]; then
  DESKTOP_PID=$(cat "$DIR/desktop-data/team-desktop.pid")
  case "$DESKTOP_PID" in
    ''|*[!0-9]*) ;;
    *) DESKTOP_COMMAND=$(/bin/ps -p "$DESKTOP_PID" -o command= 2>/dev/null || true)
       case "$DESKTOP_COMMAND" in
         *"--user-data-dir=$DIR/desktop-data"*)
           /usr/bin/osascript -l JavaScript -e "ObjC.import('AppKit'); \$.NSRunningApplication.runningApplicationWithProcessIdentifier($DESKTOP_PID).activateWithOptions(\$.NSApplicationActivateIgnoringOtherApps);"
           exit 0 ;;
       esac ;;
  esac
fi
APP="${1:-}"
if [ "$#" -gt 0 ]; then shift; fi
if [ -z "$APP" ]; then
  for CANDIDATE in /Applications/Codex.app "$HOME/Applications/Codex.app" /Applications/ChatGPT.app "$HOME/Applications/ChatGPT.app"; do
    if [ -d "$CANDIDATE" ]; then APP="$CANDIDATE"; break; fi
  done
fi
[ -d "$APP/Contents/MacOS" ] || { echo 'Install Codex desktop, or pass its .app path to desktop.sh.' >&2; exit 1; }
EXECUTABLE=$(/usr/libexec/PlistBuddy -c 'Print :CFBundleExecutable' "$APP/Contents/Info.plist")
mkdir -p "$DIR/desktop-data"
chmod 700 "$DIR/desktop-data"
if [ -f "$DIR/worker/desktopBridgeCli.js" ]; then
  exec "$NODE" "$DIR/worker/desktopBridgeCli.js" "$APP_SERVER_SOCK" "$CONTROL_SOCK" "$CODEX_HOME_DIR" "$DIR/desktop-data" "$APP/Contents/MacOS/$EXECUTABLE" "--user-data-dir=$DIR/desktop-data" "$@"
fi
exec "$NODE" "$DIR/bin/desktop-bridge.mjs" "$APP_SERVER_SOCK" "$CODEX" "$CODEX_HOME_DIR" "$DIR/desktop-data" "$APP/Contents/MacOS/$EXECUTABLE" "--user-data-dir=$DIR/desktop-data" "$@"
ATTACH_DESKTOP
} >"$DIR/bin/desktop.sh"
chmod 700 "$DIR/bin/"*.sh

# --- service ------------------------------------------------------------------
if [ "$SERVICE" = 1 ] && [ "$OS" = Darwin ]; then
  PLIST="$HOME/Library/LaunchAgents/com.agent-teams.mate.${TEAM_ID:0:8}.${DIR_SUM}.plist"
  mkdir -p "$HOME/Library/LaunchAgents"
  cat >"$PLIST" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>com.agent-teams.mate.${TEAM_ID:0:8}.${DIR_SUM}</string>
  <key>ProgramArguments</key><array><string>/bin/bash</string><string>$DIR/bin/start.sh</string></array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>5</integer>
  <key>StandardOutPath</key><string>$DIR/logs/worker.log</string>
  <key>StandardErrorPath</key><string>$DIR/logs/worker.err.log</string>
  <key>EnvironmentVariables</key><dict><key>PATH</key><string>$(dirname "$NODE"):$(dirname "$CODEX"):/usr/local/bin:/usr/bin:/bin</string></dict>
</dict></plist>
EOF
  launchctl bootout "gui/$(id -u)" "$PLIST" >/dev/null 2>&1 || true
  launchctl bootstrap "gui/$(id -u)" "$PLIST"
  say "Service registered: $PLIST (restart with: launchctl kickstart -k gui/$(id -u)/com.agent-teams.mate.${TEAM_ID:0:8}.${DIR_SUM})"
elif [ "$SERVICE" = 1 ] && command -v systemctl >/dev/null 2>&1; then
  UNIT="$HOME/.config/systemd/user/agent-teams-mate-${TEAM_ID:0:8}-${DIR_SUM}.service"
  mkdir -p "$(dirname "$UNIT")"
  SYSTEMD_LAUNCHER=$("$NODE" -e 'process.stdout.write(JSON.stringify(process.argv[1]).replaceAll("%", "%%").replaceAll("$", () => "$$"))' "$DIR/bin/start.sh")
  printf '[Unit]\nDescription=Agent Teams teammate %s\n[Service]\nExecStart=/bin/bash %s\nRestart=always\nRestartSec=5\n[Install]\nWantedBy=default.target\n' "$LABEL" "$SYSTEMD_LAUNCHER" >"$UNIT"
  systemctl --user daemon-reload && systemctl --user enable --now "$(basename "$UNIT")"
  say "Service registered: $UNIT"
else
  say "Starting the worker in the background (no service manager)"
  nohup bash "$DIR/bin/start.sh" >"$DIR/logs/worker.log" 2>&1 &
fi

# Stop only this installation, including its service restart policy. Keep runtime data.
{
  printf '#!/usr/bin/env bash\nset -euo pipefail\n'
  printf 'DIR=%q\nTEAM_PREFIX=%q\nDIR_SUM=%q\n' "$DIR" "${TEAM_ID:0:8}" "$DIR_SUM"
  cat <<'STOP_INSTALLATION'
if [ "$(uname -s)" = Darwin ]; then
  PLIST="$HOME/Library/LaunchAgents/com.agent-teams.mate.${TEAM_PREFIX}.${DIR_SUM}.plist"
  if [ -f "$PLIST" ]; then launchctl bootout "gui/$(id -u)" "$PLIST" >/dev/null 2>&1 || true; fi
elif command -v systemctl >/dev/null 2>&1; then
  systemctl --user stop "agent-teams-mate-${TEAM_PREFIX}-${DIR_SUM}.service" >/dev/null 2>&1 || true
fi
PID_FILE="$DIR/data/supervisor.pid"
[ -f "$PID_FILE" ] || exit 0
PID=$(cat "$PID_FILE")
case "$PID" in ''|*[!0-9]*) echo 'Invalid installation supervisor PID' >&2; exit 1 ;; esac
COMMAND=$(ps -p "$PID" -o command= 2>/dev/null || true)
if [ -z "$COMMAND" ]; then
  echo 'Supervisor is no longer running; retained its lock for diagnostic review.'
  exit 0
fi
case "$COMMAND" in
  "bash $DIR/bin/start.sh"|"/bin/bash $DIR/bin/start.sh") kill -TERM "$PID" ;;
  *) echo 'PID does not belong to this installation; refusing to stop it.' >&2; exit 1 ;;
esac
for _ in $(seq 1 100); do [ -f "$PID_FILE" ] || exit 0; sleep 0.1; done
echo 'Supervisor shutdown has not completed; inspect installation logs.' >&2
exit 1
STOP_INSTALLATION
} >"$DIR/bin/stop.sh"
{
  printf '#!/usr/bin/env bash\nset -euo pipefail\n'
  printf 'DIR=%q\nNODE=%q\nCONTROL_MCP_NAME=%q\nCODEX_HOME_DIR=%q\nTEAM_PREFIX=%q\nDIR_SUM=%q\n' "$DIR" "$NODE" "$CONTROL_MCP_NAME" "$CODEX_HOME_DIR" "${TEAM_ID:0:8}" "$DIR_SUM"
  cat <<'UNINSTALL_INSTALLATION'
bash "$DIR/bin/stop.sh"
"$NODE" "$DIR/worker/cli.js" mcp-remove --control-mcp-name "$CONTROL_MCP_NAME" --data-dir "$DIR/data" --codex-config "$CODEX_HOME_DIR/config.toml"
if [ "$(uname -s)" = Darwin ]; then
  PLIST="$HOME/Library/LaunchAgents/com.agent-teams.mate.${TEAM_PREFIX}.${DIR_SUM}.plist"
  [ ! -f "$PLIST" ] || rm -f "$PLIST"
elif command -v systemctl >/dev/null 2>&1; then
  UNIT="agent-teams-mate-${TEAM_PREFIX}-${DIR_SUM}.service"
  systemctl --user disable "$UNIT" >/dev/null 2>&1 || true
  [ ! -f "$HOME/.config/systemd/user/$UNIT" ] || rm -f "$HOME/.config/systemd/user/$UNIT"
  systemctl --user daemon-reload >/dev/null 2>&1 || true
fi
printf '%s\n' 'Service and owned MCP registration removed. Installation data and Codex login retained.'
UNINSTALL_INSTALLATION
} >"$DIR/bin/uninstall.sh"
chmod 700 "$DIR/bin/stop.sh" "$DIR/bin/uninstall.sh"

# --- wait for the relay handshake --------------------------------------------
say "Local App Server: unix://${APP_SERVER_SOCK}"
say "AWS relay upstream: ${RELAY_URL}"
say "Waiting for the worker to connect to its local relay on 127.0.0.1"
app_server_connect_deadline=$((SECONDS + APP_SERVER_START_TIMEOUT_SECONDS))
worker_connect_deadline=0
while true; do
  if [ -S "$APP_SERVER_SOCK" ] && [ "$worker_connect_deadline" -eq 0 ]; then
    worker_connect_deadline=$((SECONDS + 60))
  fi
  if [ "$worker_connect_deadline" -eq 0 ]; then
    [ "$SECONDS" -lt "$app_server_connect_deadline" ] || break
  else
    [ "$SECONDS" -lt "$worker_connect_deadline" ] || break
  fi
  sleep 2
  if grep -q '"state": *"connected"' "$DIR/data/worker-status.json" 2>/dev/null; then
    if [ -f "$DIR/worker/desktopBridgeCli.js" ]; then
    "$NODE" "$DIR/worker/cli.js" setup --data-dir "$DIR/data" --control-mcp-name "$CONTROL_MCP_NAME" --control-socket "$CONTROL_SOCK" --codex-config "$CODEX_HOME_DIR/config.toml"
    say "Pair this device in the Web UI with this private code:"
    cat "$DIR/data/desktop-pairing-code"
  fi
    LOCAL_RELAY_URL=$("$NODE" -e 'const s=JSON.parse(require("node:fs").readFileSync(process.argv[1],"utf8"));process.stdout.write(s.relayUrl || "local relay")' "$DIR/data/worker-status.json")
    say "Worker connected to ${LOCAL_RELAY_URL}; the local relay forwards team traffic to AWS."
    say "Connected. Team ${TEAM_ID} will enroll '${LABEL}' as a member (right away in a leaderless team, otherwise once the team has an active lead)."
    echo "  status:  bash $DIR/bin/status.sh"
    echo "  stop:    bash $DIR/bin/stop.sh"
    echo "  uninstall: bash $DIR/bin/uninstall.sh   (retains runtime data and login)"
    echo "  attach:  bash $DIR/bin/attach.sh   (optional terminal client)"
    if [ "$OS" = Darwin ]; then
      echo "  desktop: bash $DIR/bin/desktop.sh   (Codex app, same App Server)"
      if [ "$OPEN_DESKTOP" = 1 ]; then
        if [ -d "$APP_TO_OPEN/Contents/MacOS" ]; then
          say "Opening Codex desktop with your existing login"
          nohup bash "$DIR/bin/desktop.sh" "$APP_TO_OPEN" </dev/null >>"$DIR/logs/desktop.log" 2>&1 &
        else
          say "Codex desktop is not installed. Install the app, then run bin/desktop.sh to open it."
        fi
      fi
    fi
    echo "  logs:    $DIR/logs/worker.log"
    exit 0
  fi
done
echo "The worker has not reported 'connected' yet; check $DIR/logs/worker.log" >&2
exit 1
__PAYLOAD_BELOW__
